  ],

  "context_differentiations": [
    {
      "context_factor": "<factor>",
      "factor_scope": "<case_level | event_level | temporal>",
      "segments": ["<segment>"],
      "affected_parameters": ["<parameter>"],
      "statistical_evidence": "<p-value / effect size>",
      "strategy_applied": "<how encoded>"
    }
  ],

  "warnings": ["<optional>"]
}

